import{_ as r,C as s,o,c as n,j as t,a as i,E as h,ak as l}from"./chunks/framework.sV-XtlWr.js";const b=JSON.parse('{"title":"Analytics","description":"","frontmatter":{"title":"Analytics","lang":"en-US"},"headers":[],"relativePath":"features/analytics.md","filePath":"features/analytics.md","lastUpdated":1790423679000}'),d={name:"features/analytics.md"};function c(p,e,u,m,g,w){const a=s("Needs");return o(),n("div",null,[e[0]||(e[0]=t("h1",{id:"analytics",tabindex:"-1"},[i("Analytics "),t("a",{class:"header-anchor",href:"#analytics","aria-label":'Permalink to "Analytics"'},"​")],-1)),h(a,{reporter:""}),e[1]||(e[1]=l('<p>The <strong>Analytics</strong> page (<code>/analytics</code>) steps back from single runs and tests: it aggregates every project over a period you choose, to show where the suite as a whole is drifting.</p><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h2><p>The <strong>Filters</strong> block at the top sets what every widget counts, with <em>Reset</em> in its header. On a phone it folds to a one-line summary.</p><ul><li><strong>Period</strong>, with the comparison and the buckets (below). The line under it states the resolved dates, the comparison and any note (a project without the chosen selection, a deleted marker).</li><li><strong>Runs</strong>: the projects (intersected with the ones you can see), environments and branches (optional multi-select, see <a href="/guide/concepts.html#environment">Environment</a>), the branch policy (<em>Default branch</em> or <em>All branches</em>, below) and <em>Full runs only</em>, which excludes partial runs. All but the projects and the policy are the <strong>filter bar</strong> Home and project pages use.</li><li><strong>Tests</strong>: optional; a selection, test tags or browsers (below).</li></ul><p>Probe runs (the fault-injected replays <code>piwi probe</code> produces) are never counted, whatever the filters.</p><h3 id="periods" tabindex="-1">Periods <a class="header-anchor" href="#periods" aria-label="Permalink to &quot;Periods&quot;">​</a></h3><ul><li><strong>Rolling</strong>: the last 7 days to 12 months, in whole UTC days, today included.</li><li><strong>Calendar</strong>: this or last week, month, quarter or year. Boundaries follow your time zone (the one set under Settings → Localization, else your browser&#39;s); a week starts on your locale&#39;s first day.</li><li><strong>Custom range</strong>: two dates, both included.</li><li><strong>Since a marker</strong>: from a <a href="./timeline-markers.html">timeline marker</a> to now.</li><li><strong>Release cycle</strong>: between two consecutive <code>release</code> markers, the current one or the previous one.</li><li><strong>Sprint</strong>: a start date and a length, this sprint or the last.</li><li><strong>All time</strong>: everything still stored.</li></ul><h3 id="comparison-and-buckets" tabindex="-1">Comparison and buckets <a class="header-anchor" href="#comparison-and-buckets" aria-label="Permalink to &quot;Comparison and buckets&quot;">​</a></h3><p>Every change on the page is measured against the <strong>comparison</strong>: the previous period of the same length (the default), the previous calendar unit, release cycle or sprint, the same period a year earlier, or nothing.</p><p><strong>Buckets</strong> decide how the trends and the heatmap cut the period: automatic (about 31 buckets), daily, weekly or monthly. Buckets start at UTC midnight, so a heatmap cell is one UTC day.</p><h3 id="branch-policy" tabindex="-1">Branch policy <a class="header-anchor" href="#branch-policy" aria-label="Permalink to &quot;Branch policy&quot;">​</a></h3><p>By default only runs on each project&#39;s <strong>default branch</strong> count, plus runs whose branch is unknown, so a broken feature branch no longer moves the trends. The default branch is the project&#39;s setting, else the one its latest run reported, else <code>main</code>. <em>All branches</em> counts every run; branches picked in the filter bar override both.</p><h3 id="test-filter" tabindex="-1">Test filter <a class="header-anchor" href="#test-filter" aria-label="Permalink to &quot;Test filter&quot;">​</a></h3><p>The <em>Tests</em> filter narrows every number to some tests:</p><ul><li>a <strong>selection</strong>, by key: <code>smoke</code> resolves in each project to that project&#39;s <a href="/guide/test-selection.html">selection</a> with that key, so a convention shared across projects works on the cross-project page; a project without it is left out and named;</li><li><strong>test tags</strong>: tests carrying all of them;</li><li><strong>browsers</strong>: the Playwright projects the executions ran on.</li></ul><p>It means the tests that match <strong>today</strong>, with their whole history. The widgets then count from the stored executions, final attempt per test and browser, so they reach back only as far as retention keeps runs. A widget that cannot narrow (the failure clusters) says so above its card.</p><p>With one project in scope, <em>Save as selection</em> stores the tags as a selection you can run with <code>piwi run &lt;key&gt;</code>.</p><h3 id="sharing-a-view" tabindex="-1">Sharing a view <a class="header-anchor" href="#sharing-a-view" aria-label="Permalink to &quot;Sharing a view&quot;">​</a></h3><p>The address carries the scope (<code>?period=last-month&amp;sel=smoke</code>), so a copied link opens on what its sender saw; without it, the page opens on the scope you used last in this browser. To keep your own view, save a <a href="./dashboards.html">dashboard</a>.</p><h3 id="where-the-numbers-come-from" tabindex="-1">Where the numbers come from <a class="header-anchor" href="#where-the-numbers-come-from" aria-label="Permalink to &quot;Where the numbers come from&quot;">​</a></h3><p>The pass rates, run counts, durations, CI time, wasted time and regression counts are read from <strong>daily rollups</strong>, one precomputed row per project, UTC day, environment, branch and run kind, kept at ingest and checked nightly against the stored runs. When <a href="/operate/storage.html#data-retention">retention</a> deletes old runs, their numbers stay in the rollups, so a one-year pass-rate line survives a 30-day retention window. Lists of tests and clusters, and anything under a test filter, read the stored runs. The rollups also <a href="/operate/metrics.html">export</a> to a BI tool or a Prometheus scraper.</p><h2 id="widgets" tabindex="-1">Widgets <a class="header-anchor" href="#widgets" aria-label="Permalink to &quot;Widgets&quot;">​</a></h2><p>The page is the built-in <strong>Overview</strong> dashboard: headline tiles, the portfolio, insights and the heatmap in <em>Where things stand</em>; failure clusters, flaky tests, wasted CI time and time to fix in <em>Where the pain is</em>; the pass rate over time, regression velocity, CI time, suite growth and flaky debt in <em>Which way it is going</em>; browsers and slow endpoints in <em>Detail</em>. <a href="./analytics-widgets.html">Analytics widgets</a> describes each one, and the widgets the other dashboards add.</p><h2 id="from-a-number-to-its-rows" tabindex="-1">From a number to its rows <a class="header-anchor" href="#from-a-number-to-its-rows" aria-label="Permalink to &quot;From a number to its rows&quot;">​</a></h2><p>A number links to the list behind it, opened with the same period and filters. In the portfolio, a project&#39;s runs, flaky tests and open failure clusters open that project&#39;s lists; each heatmap cell opens the project&#39;s runs of that day. With one project in scope, the headline tiles and every bucket of a chart do the same. The project page says the list came from Analytics and offers <strong>Show every run</strong>.</p><h2 id="exporting-a-chart" tabindex="-1">Exporting a chart <a class="header-anchor" href="#exporting-a-chart" aria-label="Permalink to &quot;Exporting a chart&quot;">​</a></h2><p>Every chart carries a menu in its header. <strong>Copy as PNG</strong> puts the chart, with its title, on the clipboard as an image, ready to paste into a slide; a browser that cannot copy images downloads the PNG instead. <strong>Download Excel</strong> saves the numbers behind the chart as an .xlsx workbook, one row per bucket or group: numbers and dates are real cells, and a test title is never run as a formula. To send a whole dashboard, export it as a <a href="./quality-reports.html">quality report</a> instead.</p><h2 id="targets" tabindex="-1">Targets <a class="header-anchor" href="#targets" aria-label="Permalink to &quot;Targets&quot;">​</a></h2><p>A project can carry <strong>targets</strong>, set in its <strong>Settings</strong> tab: a test pass rate to reach, and limits on flaky tests, wasted CI minutes per week, the age of the oldest open failure cause and the median time to fix. Each one is optional. Over the period a dashboard shows, a target is <strong>met</strong> or <strong>missed</strong>:</p><ul><li>the headline tiles mark each number that has a target, met or missed, with one project in scope;</li><li>the portfolio&#39;s <strong>Targets</strong> column counts the targets each project meets;</li><li>the insights feed says which target a project missed, and by how much;</li><li>a quality report lists every target, met or missed, and its risks name the missed ones.</li></ul><p>A weekly target (wasted CI minutes) is scaled to the length of the period, so a 30-day period is checked against about four weeks of it.</p><h2 id="marking-what-you-changed" tabindex="-1">Marking what you changed <a class="header-anchor" href="#marking-what-you-changed" aria-label="Permalink to &quot;Marking what you changed&quot;">​</a></h2><p><a href="./timeline-markers.html">Timeline markers</a> record a deploy, a CI-runner migration or a dependency bump against a project, drawn as a vertical line across the trend charts. On the analytics page, with one project in scope every marker is drawn; across projects only <code>release</code>, <code>infra</code> and <code>incident</code> markers are, labeled with their project — so &quot;the slowdown started the day we switched runners&quot; becomes something you can see rather than remember.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><p><a href="./dashboards.html">Dashboards</a> — views of your own</p></li><li><p><a href="./quality-reports.html">Quality reports</a> — this page as a document, with <strong>Export</strong></p></li><li><p><a href="./flaky-tests.html">Flaky tests</a> — the per-project analysis these widgets aggregate</p></li><li><p><a href="./timeline-markers.html">Timeline markers</a> — annotate the trends with real-world events</p></li><li><p><a href="./ui-overview.html#analytics">UI overview</a> — where this sits in the navigation</p></li></ul>',35))])}const f=r(d,[["render",c]]);export{b as __pageData,f as default};
